import{_ as o,o as d,c as r,a2 as s}from"./chunks/framework.D66Xq0Kv.js";const p=JSON.parse('{"title":"AGENTS.md — ai-art 项目交接说明","description":"","frontmatter":{},"headers":[],"relativePath":"AGENTS.md","filePath":"AGENTS.md"}'),n={name:"AGENTS.md"};function e(i,t,a,l,g,u){return d(),r("div",null,[...t[0]||(t[0]=[s(`<h1 id="agents-md-—-ai-art-项目交接说明" tabindex="-1">AGENTS.md — ai-art 项目交接说明</h1><blockquote><p>本文件是给<strong>新 session 的 AI agent</strong> 的上下文交接。用户（下称&quot;那尔&quot;）是程序员/自学绘画者，本目录是他的&quot;AI 反馈工作流&quot;项目文档集。 读完后请遵守 §2 的沟通原则与 §5 的验证规范；§6 是当前进度与下一步。</p></blockquote><hr><h2 id="_1-项目是什么" tabindex="-1">1. 项目是什么</h2><p><strong>目标不是做 AI 工具，是学画画。</strong> 工作流（他自己命名，见其博客 2026-08-15 笔记）：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>自己画（速写到成品）→ 自己先定问题（自评前置）</span></span>
<span class="line"><span>→ AI 重绘（两条线：① 平均画师版 ② 指定老师风格版）</span></span>
<span class="line"><span>→ 对比差异，按 解剖/比例/透视/明暗/线条/构图 分类</span></span>
<span class="line"><span>→ 归档 → 统计&quot;短板雷达&quot; → 针对性练习 → 下一轮</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br></div></div><p>核心定位（他自己写的）：&quot;我这一套操作是在让 AI 对我进行<strong>反馈</strong>&quot;——AI 是镜子，不是画笔。 <strong>自动化红线</strong>：自评与差异自读永远是人的环节（对应其&quot;典型化主体是你&quot;的文艺观）。</p><h2 id="_2-用户画像与沟通原则-最重要-先读这条" tabindex="-1">2. 用户画像与沟通原则（最重要，先读这条）</h2><ul><li><strong>程序员，重度心智模型爱好者</strong>：喜欢自己建模、举一反三，&quot;知其所以然&quot;是他的硬要求——<strong>每一条命令/参数都要讲为什么</strong></li><li><strong>业务层优先，反感技术炫技</strong>：原话——&quot;我关心业务，这就像我正做着 Java 业务代码开发，我琢磨着怎么把业务跑通，你在教我怎么数据库调优&quot;。给他&quot;业务跑通的最小路径&quot;，不要泛讲原理</li><li><strong>反幻觉要求极高</strong>：他会逐条核查。已抓到过两次错误：① 把&quot;绘画回顾&quot;（二次总结）当成他博客原文引用；② 把当天（8月15日）的活笔记当成历史文献。<strong>引用必须回原文，事实必须标注验证状态</strong></li><li><strong>明确否决的</strong>：聊天模型做讲评（他试过，不靠谱）——不要再推荐</li><li><strong>反小白引导</strong>：他是程序员，不要写&quot;如果没有 git 就……&quot;这类内容</li><li><strong>心理边界</strong>：他 2025 年 10-12 月高强度学画导致内耗，2026 年 1 月停画 8 个月，现在重启。原则是&quot;唯一的压力应当来自没有享受到画画的快乐&quot;。<strong>不要施压、不要堆任务</strong></li><li>他在 README 顶部自己加了&quot;墓志铭&quot;：<strong>文档是脚手架不是收藏品，用完即弃；若发现自己在读文档而不是画画，就关机</strong>。尊重它，别鼓励囤积文档</li></ul><h2 id="_3-用户的心智模型-引用时回原文-勿转述走样" tabindex="-1">3. 用户的心智模型（引用时回原文，勿转述走样）</h2><p>原文位置：<code>D:\\DESKTOP\\CODES\\blog\\source\\_posts\\</code>（按年份目录）。<code>D:\\DESKTOP\\CODES\\blog\\绘画回顾\\</code> 是<strong>二次总结</strong>（可作索引，引用须回原文）。</p><table tabindex="0"><thead><tr><th>主题</th><th>原话/要点</th><th>原文</th></tr></thead><tbody><tr><td>绘画观（建构论）</td><td>&quot;绘画是基于空间结构的设计，我的目的不是再现，而是表现&quot;；&quot;我是在做出物体的感觉&quot;；&quot;事实不一定&#39;典型&#39;，&#39;典型&#39;比事实更加事实&quot;；毛泽东文艺观（更高更强烈更集中）</td><td><code>2025-4/11-11我的绘画观的心路历程</code></td></tr><tr><td>方法论内核</td><td>PDCA+范本法（斋藤直葵）：范本=理想输出，<strong>比较=损失函数</strong>；&quot;只能选一个老师，可以创造&#39;客观&#39;的评判标准&quot;；且已写下&quot;使用 AI 去重绘（仅限学习，注意记录修改前后对比）&quot;</td><td><code>2025-2/04-02对《三个月》前两章的复习</code></td></tr><tr><td>验证集</td><td>&quot;需要<strong>验证集</strong>！……将原图模糊后再做速写，默写，从其他画师或真实照片做风格迁移，以及完全原创。我可不能过拟合了&quot;</td><td><code>2025-4/12-03某轮次的退步是正常的</code></td></tr><tr><td>画笔优先</td><td>&quot;画画靠的是画笔&quot;；直觉模型：&quot;具体材料本身就是模型&quot;</td><td><code>2025-4/11-25画画靠的是画笔</code>、<code>2026-1/01-30直觉模型和心智模型</code></td></tr><tr><td>反馈不足（本工作流的起点）</td><td>&quot;AI 反复跟我强调反馈反馈反馈……只能说画完后偶尔做做吧&quot;</td><td><code>2025-3/08-12当前对绘画的练习方式</code></td></tr><tr><td>老师先例</td><td>&quot;<strong>图像完善</strong>，将已完成的作品喂给它让它做调整，来看我的画面有何不足（<strong>Vector 老师的文章里提过的做法，他把默写头像喂给 AI 让它细化，从而观察自己的不足</strong>）&quot;</td><td><code>2025-1/02-14ComfyUI学习01</code></td></tr><tr><td><strong>他的活笔记</strong></td><td>《实验绘画AI反馈工作流》——他自己的实验日志，<strong>会持续更新，写文档前先看它</strong></td><td><code>2026-3/08-15实验绘画AI反馈工作流.md</code></td></tr></tbody></table><h2 id="_4-已定的技术决策-不要重新论证-除非他要求" tabindex="-1">4. 已定的技术决策（不要重新论证，除非他要求）</h2><table tabindex="0"><thead><tr><th>项</th><th>决定</th><th>依据</th></tr></thead><tbody><tr><td>硬件</td><td>本地 RTX 4060 8G（推理）+ AutoDL 按需租卡（训练）</td><td>8G 训不了 SDXL（需 ~10GB）</td></tr><tr><td>底模</td><td><strong>NoobAI-XL v1.1</strong>（v-pred）；免登录镜像直链 <code>https://hf-mirror.com/Laxhar/noobai-XL-1.1/resolve/main/NoobAI-XL-v1.1.safetensors</code></td><td>官方模型卡实测</td></tr><tr><td>官方参数</td><td>Euler a / 28 步 / CFG 5 / <strong>无需 clip skip</strong> / SDXL 自带 VAE / 官方分辨率列表 / 官方提示词前缀与负向词</td><td>两个官方来源对齐（见 03）</td></tr><tr><td>控制网</td><td><strong>Chenkin-UniControl-XL</strong>（8 合 1，含 OpenPose）；<strong>必须</strong>配 <code>chinoll/ComfyUI-Advanced-ControlNet</code> 专属节点，原生节点不可用</td><td>其 HF README 实测</td></tr><tr><td>工作流基线</td><td>W1（A 贴线修正 / B 平均画师）、W2 FLUX.2 klein（本地指令修图）、W3 Qwen-Image-Edit（云端）、W5 老师风格（IP-Adapter → LoRA）</td><td>见 04</td></tr><tr><td>风格目标</td><td><strong>博老师</strong>（细节丰富）vs <strong>toshi</strong>（快速捕捉），<strong>未决</strong>——建议用 IP-Adapter 出两版 A/B 后再定</td><td>其 08-15 笔记停在&quot;我以博老师&quot;半句</td></tr><tr><td>LoRA 训练</td><td>AutoDL：无卡模式配环境（0.1 元/h）→ GPU 模式训练（24G+，几元/h）→ <code>/usr/bin/shutdown</code> 自动关机 → 产物双备份（<code>/root/autodl-fs</code> + 本地）</td><td>官方文档实测，见 10</td></tr><tr><td>多人场景</td><td>人数用标签 <code>2girls</code>；<strong>&quot;谁做什么&quot;用双人 OpenPose 骨架</strong>；身份用角色 LoRA + 区域条件（有串扰问题）</td><td>见 01 §7</td></tr><tr><td>自动化</td><td>ComfyUI 原生 API（/upload/image + /prompt + WS + /view）+ 自写认证/业务层；<strong>AutoDL 无官方远程开机 API</strong></td><td>见 12</td></tr></tbody></table><h2 id="_5-验证规范-写任何外部事实前必须遵守" tabindex="-1">5. 验证规范（写任何外部事实前必须遵守）</h2><ol><li><strong>网络工具</strong>：受限档位下 <code>curl.exe</code> / <code>Invoke-WebRequest</code> 会因 schannel 失败（<code>SEC_E_NO_CREDENTIALS</code>）。<strong>用 <code>node -e &quot;fetch(...)&quot;</code> 或 Python <code>urllib.request</code></strong></li><li><strong>链接必须实测</strong>：写进文档的链接标注三级——✅ 本会话 HTTP 实测 / 🟡 搜索或官方文档间接确认 / ⚠️ 未验证（注明原因）</li><li><strong>不确定就标注，不许编造</strong>：尤其 API 端点名、参数名、价格、控制台按钮位置</li><li><strong>大文件下载测 HEAD</strong>（状态码 + Content-Length），不要真下</li><li>临时验证脚本用完即删（用户工作区要保持干净）</li></ol><h2 id="_6-当前进度与下一步" tabindex="-1">6. 当前进度与下一步</h2><p><strong>已完成</strong>：本目录 12 份文档（README + 01~08、10~12）。 <strong>未开始（下一步，按序）</strong>：</p><ol><li>按 <code>02-安装手册.md</code> 装 ComfyUI + 4 节点 + 2 模型（他还没装）</li><li>按 <code>03</code> 跑出第一张重绘对比图（第一周目标就这一个）</li><li>按 <code>07</code> 开始闭环：自评→重绘→差异自读→归档（短板雷达要 20 张后才有数据）</li></ol><p><strong>悬而未决</strong>：</p><ul><li>学术线窄调研（AI 绘画辅导/ITS 教育反馈，2023–2026）——我提了 A/B 两案，他未选。若做：限定搜索次数与输出字数，只输出带 URL 清单</li><li>博老师 vs toshi 的风格目标选择（用 IP-Adapter 两版对照自然得出结论）</li><li>LoRA 尚未训练；IP-Adapter 尚未安装</li></ul><h2 id="_7-写作规范" tabindex="-1">7. 写作规范</h2><ul><li>语言：中文。结构：表格化、分阶段、<strong>每步&quot;做什么 + 为什么&quot;</strong></li><li>顺序铁律：<strong>业务层 → 参数层 → 对比层</strong>（这是他自己的方法论，别倒过来）</li><li>不提&quot;聊天模型讲评&quot;；不写小白引导；不重复已定决策</li><li>若他问到能力边界（如&quot;多人支持吗&quot;），要分能力层回答并给<strong>结构层/身份层/语义层</strong>的工具对应，明确标注做不到的部分</li><li>他的绘画目标：<strong>百合向、双人互动、自然的女孩子们</strong>（不是对镜头摆姿势的花瓶）；这决定了他对&quot;多人控制&quot;和&quot;互动自然感&quot;的关切</li></ul><h2 id="_8-相关路径" tabindex="-1">8. 相关路径</h2><table tabindex="0"><thead><tr><th>路径</th><th>内容</th></tr></thead><tbody><tr><td><code>D:\\DESKTOP\\AGENT_WORKSPACES\\fun\\ai-art\\</code></td><td>本项目文档（本目录）</td></tr><tr><td><code>D:\\DESKTOP\\CODES\\blog\\source\\_posts\\</code></td><td>他的博客<strong>原文</strong>（绘画相关：2023-05 至今）</td></tr><tr><td><code>D:\\DESKTOP\\CODES\\blog\\绘画回顾\\</code></td><td>绘画学习<strong>二次总结</strong>（索引可用，引用回原文）</td></tr><tr><td><code>D:\\DESKTOP\\CODES\\blog\\source\\_posts\\2026-3\\08-15实验绘画AI反馈工作流.md</code></td><td>他的活笔记（实验日志，优先看）</td></tr></tbody></table><hr><p><strong>交接一句话</strong>：他已经把想法、方法论、哲学、技术选型全部论证完毕；现在缺的只有&quot;装环境、画第一张、跑闭环&quot;。新 session 的首要任务不是再写文档，而是<strong>帮他把 ComfyUI 跑起来</strong>。</p>`,27)])])}const h=o(n,[["render",e]]);export{p as __pageData,h as default};
